// Webhook経由の場合は $json.body から、Execute Workflow Trigger経由の場合は $json から取得
const rawInput = $input.first().json;
const input = rawInput.body || rawInput;

// notionPageId または script_id の両方に対応
const scriptId = input.notionPageId || input.script_id;

if (!scriptId) {
  throw new Error('script_id or notionPageId is required');
}

// スライド数を1〜7枚に対応（7枚固定から変更）
if (!input.slides_metadata || !Array.isArray(input.slides_metadata)) {
  throw new Error('slides_metadata must be an array');
}

if (input.slides_metadata.length < 1 || input.slides_metadata.length > 7) {
  throw new Error('slides_metadata must contain between 1 and 7 items');
}

// 各スライドの必須フィールド確認
for (const slide of input.slides_metadata) {
  if (!slide.image_url) throw new Error(`Missing image_url for ${slide.section}`);
  if (!slide.duration) throw new Error(`Missing duration for ${slide.section}`);
  // motion_promptは空文字列でもOK（必須チェックを削除）
}

// script_idを統一して返す（配列として返す）
return [{
  ...input,
  script_id: scriptId
}];

// n8nの$jmespath.hash関数を使用してSHA-1ハッシュを生成
const apiSecret = 'IKxxQL7zniUB5s9TeijsChM8hAs';
const timestamp = Math.floor(Date.now() / 1000);
const folder = 'n8n_meo_wf7_slide';

const stringToSign = `folder=${folder}&timestamp=${timestamp}${apiSecret}`;

// JavaScriptの組み込みWeb Crypto APIを使用（n8nで許可されている）
const encoder = new TextEncoder();
const data = encoder.encode(stringToSign);

// SHA-1ハッシュを計算（同期的な実装）
function sha1(str) {
  function rotateLeft(n, s) {
    return (n << s) | (n >>> (32 - s));
  }

  function toHexStr(n) {
    let s = '', v;
    for (let i = 7; i >= 0; i--) {
      v = (n >>> (i * 4)) & 0xf;
      s += v.toString(16);
    }
    return s;
  }

  function utf8Encode(str) {
    return unescape(encodeURIComponent(str));
  }

  let message = utf8Encode(str);
  let msgLen = message.length;
  let words = [];

  for (let i = 0; i < msgLen; i++) {
    words[i >>> 2] |= (message.charCodeAt(i) & 0xff) << (24 - 8 * (i % 4));
  }

  words[msgLen >>> 2] |= 0x80 << (24 - 8 * (msgLen % 4));
  words[(((msgLen + 8) >>> 6) << 4) + 15] = msgLen * 8;

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  for (let i = 0; i < words.length; i += 16) {
    let w = words.slice(i, i + 16);
    for (let j = 16; j < 80; j++) {
      w[j] = rotateLeft(w[j-3] ^ w[j-8] ^ w[j-14] ^ w[j-16], 1);
    }

    let a = h0, b = h1, c = h2, d = h3, e = h4;

    for (let j = 0; j < 80; j++) {
      let f, k;
      if (j < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (j < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (j < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }

      let temp = (rotateLeft(a, 5) + f + e + k + (w[j] | 0)) | 0;
      e = d;
      d = c;
      c = rotateLeft(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) | 0;
    h1 = (h1 + b) | 0;
    h2 = (h2 + c) | 0;
    h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0;
  }

  return toHexStr(h0) + toHexStr(h1) + toHexStr(h2) + toHexStr(h3) + toHexStr(h4);
}

const signature = sha1(stringToSign);

return {
  json: {
    ...($input.first().json),
    cloudinary_timestamp: timestamp,
    cloudinary_signature: signature
  },
  binary: $input.first().binary
};

// n8nのヘルパー関数を使用してバイナリデータを取得
try {
  const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');

  // Base64エンコード
  const base64Data = binaryData.toString('base64');

  // バイナリデータのMIMEタイプを取得
  const mimeType = $binary.data.mimeType || 'image/jpeg';

  // Data URI形式に変換
  const dataUri = `data:${mimeType};base64,${base64Data}`;

  // Cloudinary認証情報
  const cloudName = 'drzmodro8';
  const apiKey = '188947963992381';
  const timestamp = $json.cloudinary_timestamp;
  const signature = $json.cloudinary_signature;
  const folder = 'n8n_meo_wf7_slide';

  // Cloudinary Upload APIを呼び出し
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.cloudinary.com/v1_1/${cloudName}/image/upload`,
    headers: {
      'Content-Type': 'application/json'
    },
    body: {
      file: dataUri,
      folder: folder,
      timestamp: timestamp,
      api_key: apiKey,
      signature: signature
    },
    json: true
  });

  return {
    json: response
  };

} catch (error) {
  // 詳細なエラー情報を返す
  return {
    json: {
      error: error.message,
      error_details: error.response?.data || error.response || 'No response data',
      status_code: error.response?.status || 'unknown',
      cloudinary_timestamp: $json.cloudinary_timestamp,
      cloudinary_signature: $json.cloudinary_signature
    }
  };
}

// 現在処理中のスライド（Cloudinary URLを含む）
const slide = $input.first().json;
const scriptId = $('Code - Validate Input').item.json.script_id;

// Cloudinary URLを使用
const imageUrl = slide.cloudinary_url;

if (!imageUrl) {
  throw new Error('Cloudinary URL not found');
}

// FAL Compose APIペイロード構築
const payload = {
  tracks: [
    {
      id: "1",
      type: "video",
      keyframes: [
        {
          url: imageUrl,
          timestamp: 0,
          duration: slide.duration
        }
      ]
    }
  ]
};

return {
  json: {
    fal_payload: JSON.stringify(payload),
    slide_metadata: slide,
    script_id: scriptId,
    slide_index: $itemIndex,
    image_url: imageUrl,  // デバッグ用
    original_gdrive_url: slide.original_image_url  // デバッグ用
  }
};

const resultData = $input.first().json;
const slideData = $('Code - Prepare FAL Payload').item.json.slide_metadata;
const scriptId = $('Code - Prepare FAL Payload').item.json.script_id;
const requestId = $('HTTP Request - Submit to FAL').item.json.request_id;
const slideIndex = $('Code - Prepare FAL Payload').item.json.slide_index;

const videoUrl = resultData.output?.video_url 
  || resultData.video_url 
  || resultData.result?.video_url;

if (!videoUrl) {
  throw new Error('Video URL not found in FAL API response');
}

return {
  json: {
    section: slideData.section,
    duration: slideData.duration,
    video_url: videoUrl,
    fal_request_id: requestId,
    motion_prompt: slideData.motion_prompt,
    filename: `video_${slideIndex + 1}_${slideData.section}.mp4`,
    text: slideData.text,
    slide_index: slideIndex,
    script_id: scriptId
  }
};

// エラー時と正常時の両方に対応
const inputData = $input.first().json;

// エラー時の処理（エラー出力から来た場合）
if (inputData.error || (!inputData.data && !inputData.success)) {
  return [{
    json: {
      success: false,
      error: inputData.error || inputData.message || 'Unknown error occurred',
      script_id: inputData.script_id || 'unknown'
    }
  }];
}

// 正常時の処理（Aggregateノードから来た場合）
const aggregatedData = inputData.data;

if (!aggregatedData || !Array.isArray(aggregatedData) || aggregatedData.length === 0) {
  return [{
    json: {
      success: false,
      error: 'No data received from Aggregate node',
      script_id: inputData.script_id || 'unknown'
    }
  }];
}

const firstItem = aggregatedData[0];
if (!firstItem || !firstItem.script_id) {
  return [{
    json: {
      success: false,
      error: 'script_id not found in aggregated data',
      script_id: 'unknown'
    }
  }];
}
const scriptId = firstItem.script_id;

const sectionOrder = ['hook', 'intro', 'point1', 'point2', 'point3', 'summary', 'cta'];

const videosMetadata = aggregatedData.sort((a, b) => {
  return sectionOrder.indexOf(a.section) - sectionOrder.indexOf(b.section);
});

return [{
  json: {
    success: true,
    script_id: scriptId,
    videos_metadata: videosMetadata,
    videos_count: videosMetadata.length,
    total_duration: videosMetadata.reduce((sum, v) => sum + v.duration, 0)
  }
}];

const slide = $input.first().json.slide_metadata;
const retryCount = $input.first().json.retry_count;

return [{
  json: {
    success: false,
    error: `Rendering timeout for ${slide.section} after ${retryCount} retries`,
    section: slide.section,
    retry_count: retryCount,
    script_id: slide.script_id || 'unknown'
  }
}];
